import{_ as l,C as r,o as n,c as s,j as d,a as e,E as o,aj as a}from"./chunks/framework.m090XgxO.js";const v=JSON.parse('{"title":"Timer","description":"","frontmatter":{},"headers":[],"relativePath":"components/timer.md","filePath":"components/timer.md","lastUpdated":1789206102000}'),h={name:"components/timer.md"},m={id:"timer",tabindex:"-1"};function b(u,t,p,g,x,f){const i=r("Badge"),c=r("XhDemo");return n(),s("div",null,[d("h1",m,[t[0]||(t[0]=e("Timer ",-1)),o(i,{type:"info",text:"计时器"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#timer","aria-label":'Permalink to "Timer <Badge type="info" text="计时器" />"'},"​",-1))]),t[3]||(t[3]=a('<p>一段可正可倒的计时：能起、能停、能接着走、能归零。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/timer" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/timer.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/timer" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/timer" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/timer.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一个自己往上走的秒表：不写内容时组件铺开时、分、秒三段，auto-start 让它挂载即开跑</p>',4)),o(c,{src:"timer/01-basic"}),t[4]||(t[4]=d("h2",{id:"示例",tabindex:"-1"},[e("示例 "),d("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=d("h3",{id:"倒着走",tabindex:"-1"},[e("倒着走 "),d("a",{class:"header-anchor",href:"#倒着走","aria-label":'Permalink to "倒着走"'},"​")],-1)),t[6]||(t[6]=d("p",null,"countdown 让它从起始值往下走，终点缺省是 0；走到终点就停在那里不再往下",-1)),o(c,{src:"timer/02-countdown"}),t[7]||(t[7]=d("h3",{id:"起停与归零",tabindex:"-1"},[e("起停与归零 "),d("a",{class:"header-anchor",href:"#起停与归零","aria-label":'Permalink to "起停与归零"'},"​")],-1)),t[8]||(t[8]=d("p",null,"自己写部件：control 是一个原生按钮，按一下就按当前状态走一步（开始 / 暂停 / 继续 / 重来）",-1)),o(c,{src:"timer/03-control"}),t[9]||(t[9]=d("h3",{id:"带天数的长计时",tabindex:"-1"},[e("带天数的长计时 "),d("a",{class:"header-anchor",href:"#带天数的长计时","aria-label":'Permalink to "带天数的长计时"'},"​")],-1)),t[10]||(t[10]=d("p",null,"时满 24 会进位到天，超过一天的计时要自己写一段 days，只写时分秒会把整天数丢掉",-1)),o(c,{src:"timer/04-days"}),t[11]||(t[11]=d("h3",{id:"三个尺寸档",tabindex:"-1"},[e("三个尺寸档 "),d("a",{class:"header-anchor",href:"#三个尺寸档","aria-label":'Permalink to "三个尺寸档"'},"​")],-1)),t[12]||(t[12]=d("p",null,"size 只写在 root 上，数字大小与起停按钮的高度一起换档，子部件不重复标注",-1)),o(c,{src:"timer/05-size"}),t[13]||(t[13]=d("h3",{id:"每一拍与到点",tabindex:"-1"},[e("每一拍与到点 "),d("a",{class:"header-anchor",href:"#每一拍与到点","aria-label":'Permalink to "每一拍与到点"'},"​")],-1)),t[14]||(t[14]=d("p",null,"tick 每过一个 interval 发一次，complete 只在走到终点那一刻发一次；到点那一拍不再发 tick",-1)),o(c,{src:"timer/06-notify"}),t[15]||(t[15]=d("h3",{id:"受控通道",tabindex:"-1"},[e("受控通道 "),d("a",{class:"header-anchor",href:"#受控通道","aria-label":'Permalink to "受控通道"'},"​")],-1)),t[16]||(t[16]=d("p",null,"给了 value 与 active 就走受控分支：value 改写即重新计时，active 翻假停在当前剩余量、翻真接着走",-1)),o(c,{src:"timer/07-controlled"}),t[17]||(t[17]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>秒表、答题计时、专注计时这类需要用户自己控制起停的场景。</li><li>会议或直播的已进行时长。</li><li>需要倒着走、并且要在中途暂停的限时任务。</li><li>验证码重发倒计时、限时活动、会话即将过期提醒这类只倒数、不需要按钮的场景：走受控通道，只给一个剩余时长。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>展示的是一个时刻而不是一段时长：用<a href="./timestamp">时间戳</a>。</li><li>表达任务完成到哪一步：用<a href="./progress">进度条</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>正着走还是倒着走由 <code>countdown</code> 决定，起点 <code>startMs</code> 与终点 <code>targetMs</code> 两个方向共用。</li><li><code>start</code> / <code>pause</code> / <code>resume</code> / <code>reset</code> 四个动作齐全，<code>control</code> 部件把它们收成一个按钮，按当前状态自动换语义。</li><li>时间只从单调时钟的两个时刻相减而来，一拍都不累加，所以停停走走也不会越走越偏。</li><li><code>interval</code> 只决定数字多久跳一次；到点由另一个精确落在终点上的定时器判定，终点不落在整拍上也不会走过头。</li><li>每一段数字是一个 <code>item</code> 部件，<code>unit</code> 说明它是天、时、分、秒还是毫秒，排版完全交给作者。</li><li><strong>受控通道</strong>：给了 <code>value</code>（剩余毫秒）或 <code>active</code> 即进受控分支——<code>value</code> 就是起点、方向锁成倒着走、终点锁成 0，改写它即从新值重新计时；<code>active</code> 翻假停在当前值、翻真接着走。受控时起停按钮不再改状态（根上落 <code>data-controlled</code>），状态归这两个 prop。</li><li><code>format</code> 把当前值铺成一串字（<code>api.text</code>），<code>precision</code> 决定取到哪一位：<code>0</code> 到秒、<code>3</code> 到毫秒，缺省 <code>3</code> 即不量化。</li><li><code>live</code> 决定时间区的读屏播报档位，缺省 <code>off</code>。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-timer&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTimerControl</code> <code>XhTimerDisplay</code> <code>XhTimerItem</code> <code>XhTimerRoot</code> <code>XhTimerSeparator</code></td></tr><tr><td>组合式函数</td><td><code>useTimer</code></td></tr><tr><td>状态机</td><td><code>timerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/timer.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;timer&quot;</code>：<strong><code>root</code></strong> · <strong><code>display</code></strong> · <code>item</code> · <code>separator</code> · <code>control</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>startMs</code></td><td><code>number</code></td><td></td><td>起始值毫秒，缺省 0。正计时从它往上走，倒计时从它往下走。</td></tr><tr><td><code>targetMs</code></td><td><code>number</code></td><td></td><td>终点值毫秒。倒计时缺省 0；正计时不给它就一直走下去，没有终点也不会通知走完。 终点落在起点的反方向（倒计时给了比起点还大的终点）时这一轮长度为 0： 显示值停在起点上，一开跑就到点。</td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td><td>倒着走，缺省假。</td></tr><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控剩余毫秒。给了它即进受控通道：它就是起点，方向锁成倒着走、终点锁成 0， startMs / targetMs / countdown 三个不再参与；改写它即把累计清零并从新值重新计时。</td></tr><tr><td><code>active</code></td><td><code>boolean</code></td><td></td><td>受控开关，缺省真。给了它即进受控通道：翻假停在当前累计值，翻真从那里接着走。 受控时起停按钮不再改状态——状态由这个 prop 说了算。</td></tr><tr><td><code>autoStart</code></td><td><code>boolean</code></td><td></td><td>挂载即开跑，缺省假。它只在挂载那一刻读一次，之后改它不再有作用。</td></tr><tr><td><code>interval</code></td><td><code>number</code></td><td></td><td>刷新间隔毫秒，缺省 1000，下限一帧。 它只决定数字多久跳一次；到点由另一个精确落在终点上的定时器判定，不受它影响。</td></tr><tr><td><code>format</code></td><td><code>string</code></td><td></td><td>文本模板，缺省 <code>HH:mm:ss</code>。D 天、H 时、m 分、s 秒、S 毫秒，重复字母的个数即最少位数。</td></tr><tr><td><code>precision</code></td><td><code>number</code></td><td></td><td>取值粒度：0 到秒、1 到十分之一秒、2 到百分之一秒、3 到毫秒。缺省 3，即不量化。</td></tr><tr><td><code>live</code></td><td><code>TimerLive</code></td><td></td><td>读屏播报档位，缺省 off。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TimerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onTick</code></td><td><code>(details: TimerTickDetails) =&gt; void</code></td><td></td><td>每一拍通知一次。到点那一拍只发 onComplete。</td></tr><tr><td><code>onComplete</code></td><td><code>(details: TimerCompleteDetails) =&gt; void</code></td><td></td><td>走到终点通知一次；中途被暂停或归零不通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>tick</code></td><td><code>TimerTickDetails</code></td><td>走过一拍；detail 为 <code>{ value: number, elapsed: number }</code></td></tr><tr><td><code>complete</code></td><td><code>TimerCompleteDetails</code></td><td>走到终点；detail 为 <code>{ value: number, elapsed: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTimerRoot</code></td><td><code>default</code></td><td><code>TimerRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>display</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code> · <code>running</code> · <code>paused</code> · <code>completed</code></p><p><strong>事件</strong>：<code>RUN.START</code> · <code>RUN.PAUSE</code> · <code>RUN.RESUME</code> · <code>RUN.RESET</code> · <code>CLOCK.TICK</code> · <code>CLOCK.SETTLE</code> · <code>CLOCK.SYNC</code></p><p><strong>判据</strong>：<code>isSettled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTimer</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>TimerPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前该显示的毫秒，已夹在起点与终点之间并按 precision 量化。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>按模板铺好的文本，也就是不自己排每一段时该显示的字。</td></tr><tr><td><code>controlled</code></td><td><code>boolean</code></td><td>走的是受控通道吗：给了 value 或 active 即是，此时起停按钮不改状态。</td></tr><tr><td><code>elapsed</code></td><td><code>number</code></td><td>累计走了多少毫秒，与方向和起始值无关。</td></tr><tr><td><code>running</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>paused</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>completed</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>countdown</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>segments</code></td><td><code>TimerSegments</code></td><td>显示值拆开的五段。</td></tr><tr><td><code>segmentText</code></td><td><code>(unit: TimerUnit) =&gt; string</code></td><td>某一段补零后的字面：天不补零，时分秒两位，毫秒三位。</td></tr><tr><td><code>controlAction</code></td><td><code>TimerControlAction</code></td><td>起停按钮这一下要做的事。</td></tr><tr><td><code>controlLabel</code></td><td><code>string</code></td><td>起停按钮的读屏名字，也是按钮里没写内容时该显示的字。</td></tr><tr><td><code>start</code></td><td><code>() =&gt; void</code></td><td>从头开跑。</td></tr><tr><td><code>pause</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>resume</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>reset</code></td><td><code>() =&gt; void</code></td><td>归零并停下。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDisplayProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TimerItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on control</td><td>按当前状态起停：没起步的开跑、在走的暂停、停在半路的接着走、走完的归零；control 是原生 button，这两个键由平台翻成 click</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>display</code></td><td><code>aria-label</code></td><td>label.time(segments)</td></tr><tr><td><code>display</code></td><td><code>aria-live</code></td><td>props.live</td></tr><tr><td><code>display</code></td><td><code>role</code></td><td>&#39;timer&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>control</code></td><td><code>aria-label</code></td><td>label[controlAction]</td></tr></tbody></table><ul><li>时间区带着整段时间的读屏名字，里面的数字与记号对读屏是隐藏的。</li><li>内建的那个名字恒按「时 分 秒」念（天数大于 0 时前面再加一段天）。屏幕上只摆了其中几段（例如只有分和秒）时它会多念一段，请用 <code>translations.time</code> 自己按摆出来的段数给名字。</li><li>内建名字是英文，换语言同样走 <code>translations.time</code>。</li><li>缺省不播报。要播报的场景（会话到期提醒这类）把 <code>live</code> 开到 <code>polite</code> 或 <code>assertive</code>，或者自己在外层另起一个 live 区，只在关口上说一句：每秒都在变的数字按 polite 播报，一分钟就是六十条打断。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/timer.css</code> 按部件选择：<code>[data-scope=&quot;timer&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-controlled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-countdown</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>display</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;running&#39; | &#39;paused&#39; | &#39;completed&#39;</td></tr><tr><td><code>item</code></td><td><code>data-unit</code></td><td>item.unit</td></tr><tr><td><code>control</code></td><td><code>data-action</code></td><td>&#39;pause&#39; | &#39;resume&#39; | &#39;reset&#39; | &#39;start&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-timer-completed-fg</code></td><td><code>display</code></td><td><code>color</code></td><td><code>state=completed</code></td><td><code>--xh-fg-muted</code></td><td>timer 的 display 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg</code></td><td><code>control</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-surface</code></td><td>timer 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-active</code></td><td><code>control</code></td><td><code>background</code></td><td><code>active</code><br><code>not(:disabled)</code></td><td><code>--xh-bg-subtle-active</code></td><td>timer 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-disabled</code></td><td><code>control</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-muted</code></td><td>timer 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-bg-hover</code></td><td><code>control</code></td><td><code>background</code></td><td><code>hover</code></td><td><code>--xh-bg-subtle-hover</code></td><td>timer 的 control 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border</code></td><td><code>control</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-control</code></td><td>timer 的 control 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-disabled</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>disabled</code></td><td><code>--xh-border-subtle</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-focus</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>focus-visible</code></td><td><code>--xh-_tone</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-border-hover</code></td><td><code>control</code></td><td><code>border-color</code></td><td><code>hover</code></td><td><code>--xh-border-control-hover</code></td><td>timer 的 control 部件 border-color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-fg</code></td><td><code>control</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timer 的 control 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-gap</code></td><td><code>control</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_timer-control-gap</code></td><td>timer 的 control 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-h</code></td><td><code>control</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_timer-control-h</code></td><td>timer 的 control 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-px</code></td><td><code>control</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_timer-control-px</code></td><td>timer 的 control 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-radius</code></td><td><code>control</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>timer 的 control 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-shadow-active</code></td><td><code>control</code></td><td><code>box-shadow</code></td><td><code>active</code><br><code>not(:disabled)</code></td><td><code>none</code></td><td>timer 的 control 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-timer-control-shadow-hover</code></td><td><code>control</code></td><td><code>box-shadow</code></td><td><code>hover</code><br><code>not(:disabled)</code></td><td><code>--xh-elevation-raised</code></td><td>timer 的 control 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-timer-digit-font-size</code></td><td><code>display</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_timer-digit-size</code></td><td>timer 的 display 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-timer-display-fg</code></td><td><code>display</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timer 的 display 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timer 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_timer-gap</code></td><td>timer 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-timer-item-fg</code></td><td><code>item</code></td><td><code>color</code></td><td><code>default</code></td><td><code>inherit</code></td><td>timer 的 item 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-separator-fg</code></td><td><code>separator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>timer 的 separator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timer-separator-px</code></td><td><code>separator</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>timer 的 separator 部件 padding-inline 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>box-shadow</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>pointer: coarse</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>时间区的排列方向钉成从左到右，<code>&lt;html dir=&quot;rtl&quot;&gt;</code> 下时分秒不会倒过来排——时间串的读序两个方向都一样。</li><li>起停按钮相对时间区的位置、以及整个组件在页面里的排布，照常跟随文字方向。</li></ul><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./button">按钮</a>配合做「开始 / 暂停 / 重来」一排控制。</li><li>与<a href="./progress">进度条</a>并排，一个说还剩多久、一个说走了几成。</li><li>走完后用<a href="./alert">警告提示</a>或<a href="./toast">提示消息</a>告诉用户下一步做什么。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>计时超过一天要自己加一段 <code>days</code>：<code>hours</code> 满 24 会进位到天，只写时分秒会把整天数丢掉。</li><li>数字用等宽字形，位数变化时分隔符才不会左右挪动，皮肤已经这样做了，自定义排版时别丢掉。</li><li>嵌在一句话里或摆在别人的数值槽里时把 <code>--xh-timer-digit-font-size</code> 写成 <code>inherit</code>，数字就跟着上下文的字号走，不再自带展示档字号。</li><li>精确到秒的倒计时别开成高频播报：读屏用户会被打断得没法做事。</li><li>每一段的数字恒由组件写进条目里，作者只声明这一段是哪个单位；写在条目里的内容留不住，下一拍就会被新的数字盖掉。要在数字旁边加字（「时」「分」）请写进记号部件。</li><li>起停按钮的名字（读屏念的那个）恒由组件按当前状态给，换语言走 <code>translations</code>，别硬编码。按钮里显示的那行字两个适配器不一样，见下一条。</li><li>两个适配器的差别只有三处，写标记前先对一眼： <ul><li><strong>默认结构</strong>：Vue 的根组件不写内容时会自动铺开「时:分:秒」；Web Components 侧元素不生成任何结构，root 与 display 一个都不能少，每一段与记号都要作者自己写出来。</li><li><strong>按钮里的字</strong>：Vue 的起停按钮不写内容时填当前动作的名字（Start / Pause / Resume / Reset）；Web Components 侧那行字归作者写（按钮里多半是个图标），元素只换按钮的 <code>data-action</code> 与读屏名字。</li><li><strong>记号的缺省</strong>：Vue 的记号部件不写内容时是一个冒号；Web Components 侧记号里的字一律归作者写。</li></ul></li><li>Web Components 侧条目上的 <code>unit</code> 是作者的声明、不是元素写回的状态，改它本身不会另排一次接线：停着的时候改完要等下一次属性变更或起跑才生效（跑起来时每一拍都会重接一次，自然跟上）。</li><li>走完之后要有明确的去处：或者归零重来，或者跳去下一步，别停在 00:00 就不动了。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它显示当前时刻：它只认时长，不认日历也不认时区。</li><li>只给终点不给起点做倒计时：起点缺省是 0，倒着走会一开跑就到点，屏幕上恒是 00:00。要倒计多久写进 <code>startMs</code>。</li><li>挂载后再改 <code>autoStart</code> 指望它开跑：那个 prop 只在挂载那一刻读一次，起停请用动作或 <code>control</code>。</li><li>走完了不发生任何事，用户白等一场。</li><li>走完之后停在 00:00 就不动了，既不归零也不给下一步。</li><li>页面切到后台后计时漂移却不校正：时间只从单调时钟的两个时刻相减，别自己按拍累加。</li></ul>',59))])}const q=l(h,[["render",b]]);export{v as __pageData,q as default};
